const translate = (value) => translations.get(value) ?? value
  .replace(/^Deployment status: succeeded/, "Статус публикации: успешно")
  .replace(/^Deployment status: /, "Статус публикации: ");

function render(markdown) {
  const lines = markdown.split("\n").map((line) => {
    const prefix = line.startsWith("- ") ? "- " : line.startsWith("## ") ? "## " : line.startsWith("# ") ? "# " : "";
    return prefix + escapeHtml(translate(line.slice(prefix.length)));
  });
  let listOpen = false;
  const output = [];
  for (const line of lines) {
    if (line.startsWith("- ")) {
      if (!listOpen) output.push("<ul>");
      listOpen = true;
      output.push(`<li>${line.slice(2)}</li>`);
      continue;
    }
    if (listOpen) output.push("</ul>");
    listOpen = false;
    if (line.startsWith("## ")) output.push(`<h2>${line.slice(3)}</h2>`);
    else if (line.startsWith("# ")) output.push(`<h1>${line.slice(2)}</h1>`);
    else if (line) output.push(`<p>${line}</p>`);
  }
  if (listOpen) output.push("</ul>");
  return output.join("\n");
}

const [changelog, decisions] = await Promise.all([
  readFile(new URL("../CHANGELOG.md", import.meta.url), "utf8"),
  readFile(new URL("../DECISIONS.md", import.meta.url), "utf8")
]);

const body = `<main class="log-grid"><section class="log-column" aria-labelledby="changelog-heading">${render(changelog).replace("<h1>", '<h1 id="changelog-heading">')}</section><section class="log-column" aria-labelledby="decisions-heading">${render(decisions).replace("<h1>", '<h1 id="decisions-heading">')}</section></main>`;
